import { useLocation } from "react-router-dom";
import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import Header from "../../components/Header";
import Footer from "../../components/Footer";
import { FaUserCog, FaVideo, FaLifeRing } from "react-icons/fa";
import Skeleton from 'react-loading-skeleton';
import 'react-loading-skeleton/dist/skeleton.css';
import styled, { keyframes } from "styled-components";

const Tutorial = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const [producto, setProducto] = useState(null);
  const [mainImage, setMainImage] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    setLoading(true);
    setTimeout(() => {
      if (location.state?.producto) {
        const productoData = location.state.producto;
        localStorage.setItem("productoSeleccionado", JSON.stringify(productoData));
        setProducto(productoData);
        setMainImage(
          Array.isArray(productoData.Imagen) && productoData.Imagen.length > 0
            ? productoData.Imagen[0]
            : productoData.Imagen
        );
      } else {
        const storedProducto = localStorage.getItem("productoSeleccionado");
        if (storedProducto) {
          const parsedProducto = JSON.parse(storedProducto);
          setProducto(parsedProducto);
          setMainImage(
            Array.isArray(parsedProducto.Imagen) && parsedProducto.Imagen.length > 0
              ? parsedProducto.Imagen[0]
              : parsedProducto.Imagen
          );
        }
      }
      setLoading(false);
    }, 800);
  }, [location.state]);

  if (loading || !producto) {
    return (
      <MainContainer>
        <Header />
        <HeroSkeleton>
          <div>
            <Skeleton height={220} width={260} style={{ borderRadius: 18 }} />
          </div>
          <div style={{ flex: 1, marginLeft: 32 }}>
            <Skeleton height={40} width={320} style={{ marginBottom: 18 }} />
            <Skeleton height={25} count={3} width="80%" style={{ marginBottom: 10 }} />
            <Skeleton height={20} count={2} width="60%" style={{ marginBottom: 10 }} />
          </div>
        </HeroSkeleton>
        <Skeleton style={{marginTop: 32, borderRadius: 18}} height={350} />
        <Footer />
      </MainContainer>
    );
  }

  return (
    <MainContainer>
      <Header />
      <HeroSection>
        <HeroImageContainer>
          {mainImage ? (
            <HeroImage
              src={mainImage}
              alt="Producto"
              onError={(e) => {
                e.target.onerror = null;
                e.target.src = 'https://via.placeholder.com/400x300?text=Imagen+no+disponible';
              }}
            />
          ) : (
            <ImagePlaceholder>
              <FaUserCog size={52} />
              <span>Imagen no disponible</span>
            </ImagePlaceholder>
          )}
        </HeroImageContainer>
        <HeroDetails>
          <h1>{producto.Nombre || "Producto sin nombre"}</h1>
          <HeroInfo>
            {producto.Modelo && (
              <InfoBox>
                <strong>Modelo</strong>
                <span>{producto.Modelo}</span>
              </InfoBox>
            )}
            {producto["Número de serie"] && (
              <InfoBox>
                <strong>Serie</strong>
                <span>{producto["Número de serie"]}</span>
              </InfoBox>
            )}
            {producto["Fecha de compra"] && (
              <InfoBox>
                <strong>Compra</strong>
                <span>{producto["Fecha de compra"]}</span>
              </InfoBox>
            )}
          </HeroInfo>
          <HeroDesc>
            Tutoriales del producto.
          </HeroDesc>
        </HeroDetails>
        
      </HeroSection>

      <FadeSection>
        <CardsFlex>
          <InfoCardVibrant style={{ maxWidth: 540, margin: "0 auto" }}>
            <SectionTitle>
              <FaUserCog /> Tutorial del producto
              <Badge tutorial>TUTORIAL</Badge>
            </SectionTitle>
            <InfoText>
              {producto["Soporte y mantenimiento"] || "Para asistencia técnica con este producto, por favor contacte a nuestro equipo de soporte."}
            </InfoText>
            {producto.Video && (
              <VideoSection>
                <DetailItem>
                  <FaVideo style={{ marginRight: 8, color: "#10b981" }} />
                  <span><strong>Video tutorial</strong></span>
                </DetailItem>
                <VideoLink
                  href={producto.Video}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  Ver video tutorial del producto
                </VideoLink>
              </VideoSection>
            )}
          </InfoCardVibrant>
        </CardsFlex>
      </FadeSection>
      <Footer />
    </MainContainer>
  );
};

export default Tutorial;

// Estilos (los mismos que en Manual.js)
const fadeUp = keyframes`
  from { opacity: 0; transform: translateY(40px);}
  to { opacity: 1; transform: translateY(0);}
`;

const MainContainer = styled.div`
  font-family: 'Poppins', sans-serif;
  background: #f7fafd;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
`;

const HeroSection = styled.section`
  display: flex;
  align-items: flex-end;
  background: linear-gradient(95deg,#e8eefd 60%,#ffffff 100%);
  border-radius: 28px;
  box-shadow: 0 8px 32px rgba(44,80,150,0.10);
  margin: 28px auto 0 auto;
  max-width: 1100px;
  padding: 38px 38px 26px 38px;
  position: relative;
  gap: 44px;
  @media (max-width: 900px) {
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: 22px;
    padding: 26px 12px 22px 12px;
  }
`;

const HeroImageContainer = styled.div`
  min-width: 220px;
  max-width: 260px;
  background: #fff;
  border-radius: 16px;
  box-shadow: 0 3px 18px rgba(44,80,150,0.08);
  padding: 18px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 180px;
  @media (max-width: 600px) {
    min-width: 120px;
    max-width: 100vw;
    padding: 10px;
  }
`;

const HeroImage = styled.img`
  width: 100%;
  height: auto;
  max-height: 210px;
  border-radius: 12px;
  object-fit: contain;
  @media (max-width: 600px) {
    max-height: 110px;
    border-radius: 7px;
  }
`;

const ImagePlaceholder = styled.div`
  background: #f0f3fa;
  border-radius: 10px;
  height: 160px;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: #7f8c8d;
  font-size: 1rem;
  gap: 8px;
`;

const HeroDetails = styled.div`
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 10px;
  h1 {
    font-size: 2.25rem;
    color: #193965;
    font-weight: 700;
    margin-bottom: 8px;
    letter-spacing: 0.5px;
    @media (max-width: 600px) {
      font-size: 1.2rem;
      margin-bottom: 4px;
    }
  }
`;

const HeroInfo = styled.div`
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
  margin: 0 0 16px 0;
  @media (max-width: 700px) {
    justify-content: center;
    gap: 14px;
  }
`;

const InfoBox = styled.div`
  background: #fff;
  border-radius: 10px;
  box-shadow: 0 2px 8px rgba(44,80,150,0.07);
  padding: 8px 22px;
  min-width: 100px;
  display: flex;
  flex-direction: column;
  align-items: center;
  strong {
    color: #345475;
    font-size: 0.99rem;
    margin-bottom: 2px;
    font-weight: 600;
  }
  span {
    color: #1a222b;
    font-size: 1.08rem;
    font-weight: 500;
  }
  @media (max-width: 600px) {
    padding: 5px 9px;
    min-width: 70px;
    span { font-size: 0.93rem;}
    strong { font-size: 0.89rem;}
  }
`;

const HeroDesc = styled.div`
  color: #3d5a80;
  font-size: 1.13rem;
  font-weight: 500;
  background: #eaf2fd;
  border-radius: 8px;
  padding: 5px 20px;
  display: inline-block;
  margin-top: 4px;
  letter-spacing: 0.2px;
  @media (max-width: 600px) {
    font-size: .97rem;
    padding: 4px 9px;
    border-radius: 5px;
  }
`;

const SoporteBtn = styled.button`
  position: absolute;
  top: 28px;
  right: 38px;
  background: #345475;
  color: #fff;
  border: none;
  border-radius: 50px;
  padding: 10px 26px 10px 22px;
  font-size: 1.01rem;
  font-weight: 600;
  box-shadow: 0 2px 14px rgba(44,80,150,0.13);
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  transition: background 0.19s, box-shadow 0.19s;
  z-index: 2;
  &:hover {
    background: #233553;
    box-shadow: 0 4px 18px rgba(44,80,150,0.18);
  }
  @media (max-width: 900px) {
    position: static;
    margin: 16px auto 0 auto;
  }
`;

const FadeSection = styled.div`
  animation: ${fadeUp} 0.48s;
  margin: 38px auto 42px auto;
  max-width: 1100px;
  @media (max-width: 600px) {
    margin: 16px auto 22px auto;
    max-width: 99vw;
  }
`;

const CardsFlex = styled.div`
  display: flex;
  align-items: stretch;
  justify-content: center;
  gap: 28px;
  @media (max-width: 950px) {
    flex-direction: column;
    gap: 24px;
  }
`;

const InfoCardVibrant = styled.div`
  background: linear-gradient(120deg, #f8fafc 90%, #e0e7ff 100%);
  border-radius: 22px;
  padding: 36px 28px 30px 28px;
  box-shadow: 0 8px 40px 0 rgba(52,84,117,0.11);
  min-width: 310px;
  flex: 1;
  animation: ${fadeUp} 0.85s;
  border: 2.5px solid #e0e7ff;
  position: relative;
  @media (max-width: 950px) {
    min-width: 0;
    width: 100%;
    padding: 19px 8px 18px 8px;
    border-radius: 11px;
  }
`;

const Badge = styled.span`
  margin-left: 16px;
  font-size: 0.85rem;
  font-weight: 700;
  padding: 3px 13px;
  border-radius: 20px;
  background: ${({ preventivo, correctivo, tutorial }) =>
    preventivo ? "#d1fae5"
    : correctivo ? "#dbeafe"
    : tutorial ? "#fef9c3"
    : "#e5e7eb"};
  color: ${({ preventivo, correctivo, tutorial }) =>
    preventivo ? "#059669"
    : correctivo ? "#2563eb"
    : tutorial ? "#c27803"
    : "#374151"};
  letter-spacing: 1px;
  vertical-align: middle;
`;

const SectionTitle = styled.h3`
  font-size: 1.22rem;
  color: #2c3e50;
  font-weight: 700;
  margin-bottom: 13px;
  display: flex;
  align-items: center;
  gap: 13px;
  @media (max-width: 600px) {
    font-size: 1.05rem;
    margin-bottom: 8px;
    gap: 8px;
  }
`;

const InfoText = styled.div`
  font-size: 16px;
  color: #555;
  line-height: 1.65;
  margin-bottom: 17px;
  ul {
    padding-left: 28px;
    margin: 10px 0;
  }
  li {
    margin-bottom: 7px;
    line-height: 1.5;
  }
  @media (max-width: 600px) {
    font-size: .95rem;
    margin-bottom: 11px;
    ul { padding-left: 18px; }
    li { margin-bottom: 4px; }
  }
`;

const VideoSection = styled.div`
  margin: 20px 0 0 0;
  padding: 14px;
  background: #f8fafc;
  border-radius: 10px;
`;

const VideoLink = styled.a`
  color: #3498db;
  text-decoration: none;
  font-weight: 500;
  margin-top: 10px;
  display: inline-block;
  &:hover {
    color: #2980b9;
    text-decoration: underline;
  }
`;

const DetailItem = styled.div`
  margin-bottom: 10px;
  font-size: 15px;
  color: #555;
  line-height: 1.5;
  display: flex;
  align-items: center;
  @media (max-width: 600px) {
    font-size: .90rem;
    margin-bottom: 5px;
  }
`;

const HeroSkeleton = styled.div`
  display: flex;
  align-items: flex-end;
  background: linear-gradient(95deg,#e8eefd 60%,#ffffff 100%);
  border-radius: 28px;
  box-shadow: 0 8px 32px rgba(44,80,150,0.10);
  margin: 28px auto 0 auto;
  max-width: 1100px;
  padding: 38px 38px 26px 38px;
  gap: 44px;
  @media (max-width: 900px) {
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: 22px;
    padding: 26px 12px 22px 12px;
  }
`;